mapper.select:
SELECT DATE_FORMAT(STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d'),'%Y"年"%m"月"%d"日"') cdate, A.prodestablish,--产品成立 B.nhgexpire,--逆回购到期 C.zhgsq,--正回购首期 D.ccexpire,--拆出到期 E.crsq,--拆入首期 F.assetsale,--资产卖出 G.assetexpire,--资产到期 H.assetpayments,--资产中间收息 IFNULL(A.prodestablish,0)+IFNULL(B.nhgexpire,0)+IFNULL(C.zhgsq,0)+IFNULL(D.ccexpire,0)+IFNULL(E.crsq,0)+IFNULL(F.assetsale,0)+IFNULL(G.assetexpire,0)+IFNULL(H.assetpayments,0) calclr, I.prodexpire,--产品到期 J.nhgsq, --逆回购首期 K.zhgexpire,--正回购到期 L.ccsq,--拆出首期 M.crexpire, --拆入到期 N.assetbuy,--资产买入 IFNULL(I.prodexpire,0)+IFNULL(J.nhgsq,0)+IFNULL(K.zhgexpire,0)+IFNULL(L.ccsq,0)+IFNULL(M.crexpire,0)+IFNULL(N.assetbuy,0) calclc, (IFNULL(A.prodestablish,0)+IFNULL(B.nhgexpire,0)+IFNULL(C.zhgsq,0)+IFNULL(D.ccexpire,0)+IFNULL(E.crsq,0)+IFNULL(F.assetsale,0)+IFNULL(G.assetexpire,0)+IFNULL(H.assetpayments,0))- (IFNULL(I.prodexpire,0)+IFNULL(J.nhgsq,0)+IFNULL(K.zhgexpire,0)+IFNULL(L.ccsq,0)+IFNULL(M.crexpire,0)+IFNULL(N.assetbuy,0)) cleancashflow FROM --产品成立 (select sum(TRADE_AMT) prodestablish from ( SELECT SINGLEDEAL.TOTLE_TRADE_ID, SINGLEDEAL.PS, SINGLEDEAL.FINPROD_TYPE2, SINGLEDEAL.trade_date, PADD.portfolio_id, SINGLEDEAL.FINPROD_ID, SINGLEDEAL.TRADE_AMT, SINGLEDEAL.SHARE_AMT FROM TRD_PRODUCT_DEAL SINGLEDEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD PADD ON SINGLEDEAL.TRADE_ID = PADD.TRADE_ID left join FIN_PRODUCT fp on PADD.portfolio_id = fp.FINPROD_MARKET_ID left join FIN_PRODUCT_ADD pa on PA.FINPROD_ID = fp.FINPROD_ID left join sys_user users on users.USER_NAME = pa.prod_manager WHERE SINGLEDEAL.trade_date = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and SINGLEDEAL.ps IN ('C1', 'C2', 'C4', 'C5', 'C7', 'C20', 'T01', 'T02', 'T03', 'T04', 'T07', 'T08', 'T09', 'T11', 'T13', 'T23', 'T24', 'T38', 'T39', 'T46', 'T47', 'T48') and fp.P_FINPROD_ID is null and SINGLEDEAL.IS_CANCEL = 'N' and TRADE_STATUS = '01' and TRADE_AMT > 0 and not exists (select 1 from fin_product pro where SINGLEDEAL.counter_id = pro.finprod_market_id)
and users.USER_NAME in
#{item}
union all
SELECT SINGLEDEAL.TOTLE_TRADE_ID, SINGLEDEAL.PS, SINGLEDEAL.FINPROD_TYPE2, SINGLEDEAL.trade_date, PADD.portfolio_id, SINGLEDEAL.FINPROD_ID, SINGLEDEAL.TRADE_AMT, SINGLEDEAL.SHARE_AMT FROM TRD_PRODUCT_DEAL SINGLEDEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD PADD ON SINGLEDEAL.TRADE_ID = PADD.TRADE_ID left join FIN_PRODUCT fp on PADD.portfolio_id = fp.FINPROD_MARKET_ID left join FIN_PRODUCT_ADD pa on PA.FINPROD_ID = fp.FINPROD_ID left join sys_user users on users.USER_NAME = pa.prod_manager WHERE SINGLEDEAL.trade_date = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and SINGLEDEAL.ps IN ( 'T22') and fp.P_FINPROD_ID is null and SINGLEDEAL.IS_CANCEL = 'N' and TRADE_STATUS = '01' and SINGLEDEAL.FEE_AMT is null and TRADE_AMT > 0 and not exists (select 1 from fin_product pro where SINGLEDEAL.counter_id = pro.finprod_market_id)
and users.USER_NAME in
#{item}
union all
SELECT SINGLEDEAL.TOTLE_TRADE_ID, SINGLEDEAL.PS, SINGLEDEAL.FINPROD_TYPE2, SINGLEDEAL.trade_date, PADD.portfolio_id, SINGLEDEAL.FINPROD_ID, SINGLEDEAL.TRADE_AMT, SINGLEDEAL.SHARE_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL SINGLEDEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD PADD ON SINGLEDEAL.TOTLE_TRADE_ID = PADD.TRADE_ID left join FIN_PRODUCT fp on PADD.portfolio_id = fp.FINPROD_MARKET_ID left join FIN_PRODUCT_ADD pa on PA.FINPROD_ID = fp.FINPROD_ID left join sys_user users on users.USER_NAME = pa.prod_manager WHERE SINGLEDEAL.trade_date = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and SINGLEDEAL.ps IN ( 'T07', 'T08', 'T38') and fp.P_FINPROD_ID is null and SINGLEDEAL.IS_CANCEL = 'N' and TRADE_STATUS = '01' AND SINGLEDEAL.P_TOTLE_TRADE_ID IS not NULL and not exists (select 1 from fin_product pro where SINGLEDEAL.counter_id = pro.finprod_market_id) and SINGLEDEAL.ps in ('T07','T08') and SINGLEDEAL.ps != 'F16'
and users.USER_NAME in
#{item}
) where ps in ('C1', 'C2') and FINPROD_TYPE2 is not null) A, --逆回购到期 (select sum(TRADE_AMT) nhgexpire from ( SELECT SINGLEDEAL.TOTLE_TRADE_ID, SINGLEDEAL.PS, SINGLEDEAL.FINPROD_TYPE2, SINGLEDEAL.trade_date, PADD.portfolio_id, SINGLEDEAL.FINPROD_ID, SINGLEDEAL.TRADE_AMT, SINGLEDEAL.SHARE_AMT FROM TRD_PRODUCT_DEAL SINGLEDEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD PADD ON SINGLEDEAL.TRADE_ID = PADD.TRADE_ID left join FIN_PRODUCT fp on PADD.portfolio_id = fp.FINPROD_MARKET_ID left join FIN_PRODUCT_ADD pa on PA.FINPROD_ID = fp.FINPROD_ID left join sys_user users on users.USER_NAME = pa.prod_manager WHERE SINGLEDEAL.trade_date = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and SINGLEDEAL.ps IN ('C1', 'C2', 'C4', 'C5', 'C7', 'C20', 'T01', 'T02', 'T03', 'T04', 'T07', 'T08', 'T09', 'T11', 'T13', 'T23', 'T24', 'T38', 'T39', 'T46', 'T47', 'T48') and fp.P_FINPROD_ID is null and SINGLEDEAL.IS_CANCEL = 'N' and TRADE_STATUS = '01' and TRADE_AMT > 0 and not exists (select 1 from fin_product pro where SINGLEDEAL.counter_id = pro.finprod_market_id)
