#{item}
) where FINPROD_TYPE2 in ('F03','F05') and ps = 'T07' ) B, --正回购首期 (select sum(TRADE_AMT) zhgsq from ( SELECT SINGLEDEAL.TOTLE_TRADE_ID, SINGLEDEAL.PS, SINGLEDEAL.FINPROD_TYPE2, SINGLEDEAL.trade_date, PADD.portfolio_id, SINGLEDEAL.FINPROD_ID, SINGLEDEAL.TRADE_AMT, SINGLEDEAL.SHARE_AMT FROM TRD_PRODUCT_DEAL SINGLEDEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD PADD ON SINGLEDEAL.TRADE_ID = PADD.TRADE_ID left join FIN_PRODUCT fp on PADD.portfolio_id = fp.FINPROD_MARKET_ID left join FIN_PRODUCT_ADD pa on PA.FINPROD_ID = fp.FINPROD_ID left join sys_user users on users.USER_NAME = pa.prod_manager WHERE SINGLEDEAL.trade_date = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and SINGLEDEAL.ps IN ('C1', 'C2', 'C4', 'C5', 'C7', 'C20', 'T01', 'T02', 'T03', 'T04', 'T07', 'T08', 'T09', 'T11', 'T13', 'T23', 'T24', 'T38', 'T39', 'T46', 'T47', 'T48') and fp.P_FINPROD_ID is null and SINGLEDEAL.IS_CANCEL = 'N' and TRADE_STATUS = '01' and TRADE_AMT > 0 and not exists (select 1 from fin_product pro where SINGLEDEAL.counter_id = pro.finprod_market_id)
