SELECT DATE_FORMAT(STR_TO_DATE(#{searchDateFuture,jdbcType=VARCHAR},'%Y-%m-%d'),'%Y"年"%m"月"%d"日"') cdate, A.nhgexpire,--逆回购到期 C.ccexpire,--拆出到期 E.assetexpire,--资产到期 F.assetpayments,--资产中间收息 IFNULL(A.nhgexpire,0)+IFNULL(C.ccexpire,0)+IFNULL(E.assetexpire,0)+IFNULL(F.assetpayments,0) calclr,--现金流入-小计 G.prodexpire,--产品到期 I.zhgexpire,--正回购到期 K.crexpire,--拆入到期 IFNULL(G.prodexpire,0)+IFNULL(I.zhgexpire,0)+IFNULL(K.crexpire,0) calclc,--现金流出-小计 (IFNULL(A.nhgexpire,0)+IFNULL(C.ccexpire,0)+IFNULL(E.assetexpire,0)+IFNULL(F.assetpayments,0))- (IFNULL(G.prodexpire,0)+IFNULL(I.zhgexpire,0)+IFNULL(K.crexpire,0)) cleancashflow--净现金流 FROM --逆回购到期 (select sum(CASHFLOW) nhgexpire from ( select tmp.* from (select distinct '' PS, fcp.PAY_DATE mdate, pp.PORTFOLIO_ID, psp.FINPROD_ID, fp.FINPROD_TYPE2 CASHFLOWTYPE, fcp.CASH_TYPE, case WHEN FP.FINPROD_TYPE2 = 'F01' THEN ROUND(psp.AMOUNT * fcp.CASH_AMT, 2) WHEN FP.FINPROD_TYPE2 in ('F16', 'F24') THEN psp.AMOUNT else ROUND(psp.AMOUNT * fcp.CASH_AMT / IFNULL(fcp.CASH_BASEAMT, 1) / 1, 2) end as CASHFLOW from PTL_SEC_POSITION psp left join PTL_PORTFOLIO pp on psp.PORTFOLIO_ID = pp.PORTFOLIO_ID left join FIN_CASH_PLAN fcp on fcp.FINPROD_ID = psp.FINPROD_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON (PSP.PORTFOLIO_ID = PRODADD.PORTFOLIO_ID or pp.PARENT_PORTFOLIO_ID = PRODADD.PORTFOLIO_ID) LEFT JOIN FIN_PRODUCT PROD ON PRODADD.FINPROD_ID = PROD.FINPROD_ID where PROD.VDATE <= FCP.MDATE and psp.CDATE = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') - 1 and FCP.PAY_DATE = STR_TO_DATE(#{searchDateFuture,jdbcType=VARCHAR},'%Y-%m-%d') and psp.AMOUNT > 0 and psp.hoding_type = '03' and FP.FINPROD_TYPE2 not in ('F16', 'F24')
union all select '' PS, fp.mdate, psp.portfolio_id, psp.finprod_id, FP.FINPROD_TYPE2 CASHFLOWTYPE, '' CASH_TYPE, psp.amount CASHFLOW from ptl_sec_position psp left join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID where (FP.FINPROD_TYPE2 in ('F16', 'F24')) and psp.CDATE = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') - 1 and fp.mdate = STR_TO_DATE(#{searchDateFuture,jdbcType=VARCHAR},'%Y-%m-%d')
union all select asset.ps, asset.mdate, assetadd.PORTFOLIO_ID, asset.trade_id, asset.FINPROD_TYPE2 CASHFLOWTYPE, '' CASH_TYPE, trade.m_trade_amt CASHFLOW from trd_product_deal asset left join fin_trade_product trade on asset.trade_id = trade.finprod_id left join trd_product_deal_add assetadd on asset.trade_id = assetadd.trade_id where asset.FINPROD_TYPE2 IN ('F03', 'F05', 'F02', 'F04','F08', 'F09', 'F25') and asset.ps = 'T01' and asset.is_cancel = 'N' and asset.TRADE_STATUS='01' and trade.BRANCH = '0' and asset.mDATE = STR_TO_DATE(#{searchDateFuture,jdbcType=VARCHAR},'%Y-%m-%d')) tmp left join FIN_PRODUCT fp on tmp.portfolio_id = fp.FINPROD_MARKET_ID left join FIN_PRODUCT_ADD pa on PA.FINPROD_ID = fp.FINPROD_ID left join sys_user users on users.USER_NAME = pa.prod_manager where fp.P_FINPROD_ID is null
and users.USER_NAME in
#{item}
) where CASHFLOWTYPE in ('F03','F05')) A, --拆出到期 (select sum(CASHFLOW) ccexpire from ( select tmp.* from (select distinct '' PS, fcp.PAY_DATE mdate, pp.PORTFOLIO_ID, psp.FINPROD_ID, fp.FINPROD_TYPE2 CASHFLOWTYPE, fcp.CASH_TYPE, case WHEN FP.FINPROD_TYPE2 = 'F01' THEN ROUND(psp.AMOUNT * fcp.CASH_AMT, 2) WHEN FP.FINPROD_TYPE2 in ('F16', 'F24') THEN psp.AMOUNT else ROUND(psp.AMOUNT * fcp.CASH_AMT / IFNULL(fcp.CASH_BASEAMT, 1) / 1, 2) end as CASHFLOW from PTL_SEC_POSITION psp left join PTL_PORTFOLIO pp on psp.PORTFOLIO_ID = pp.PORTFOLIO_ID left join FIN_CASH_PLAN fcp on fcp.FINPROD_ID = psp.FINPROD_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON (PSP.PORTFOLIO_ID = PRODADD.PORTFOLIO_ID or pp.PARENT_PORTFOLIO_ID = PRODADD.PORTFOLIO_ID) LEFT JOIN FIN_PRODUCT PROD ON PRODADD.FINPROD_ID = PROD.FINPROD_ID where PROD.VDATE <= FCP.MDATE and psp.CDATE = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') - 1 and FCP.PAY_DATE = STR_TO_DATE(#{searchDateFuture,jdbcType=VARCHAR},'%Y-%m-%d') and psp.AMOUNT > 0 and psp.hoding_type = '03' and FP.FINPROD_TYPE2 not in ('F16', 'F24')
